62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
73	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
74	     * addresses are lower-cased before being stored.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** An owner's postcode, when supplied, must be exactly four digits. */
80	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
81	
82	    /**
83	     * Disposable e-mail domains an owner may not sign up with. An email whose domain (the part after
84	     * the '@', compared case-insensitively) is on this blocklist is rejected with a 400.
85	     */
86	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
87	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    /**
90	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
91	     * named logger keeps them addressable independently of the class's diagnostic logging.
92	     */
93	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
94	
95	    /**
96	     * Maximum number of owners a single city may contain. A create that would take the owner's city
97	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
98	     */
99	    private static final int CITY_OWNER_LIMIT = 50;
100	
101	    /**
102	     * Maximum number of owners that may be registered on a single day. A create that would take the
103	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
104	     * have already been created that day - is rejected with a 429.
105	     */
106	    private static final int DAILY_OWNER_LIMIT = 100;
107	
108	    /**
109	     * Number of owners that must already have been created for a given day before the create
110	     * response flags a bulk sign-up. When more than this many owners already share a
111	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
112	     */
113	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
114	
115	    /**
116	     * Fixed list of public holidays. A registration date that lands on one of these dates is treated
117	     * like a weekend and rolled forward to the next non-holiday business day.
118	     */
119	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
120	        LocalDate.of(2026, 1, 1),
121	        LocalDate.of(2026, 1, 26),
122	        LocalDate.of(2026, 4, 25),
123	        LocalDate.of(2026, 12, 25),
124	        LocalDate.of(2026, 12, 28));
125	
126	    private final ClinicService clinicService;
127	
128	    private final OwnerMapper ownerMapper;
129	
130	    private final PetMapper petMapper;
131	
132	    private final VisitMapper visitMapper;
133	
134	    public OwnerRestControllerV1(ClinicService clinicService,
135	                                 OwnerMapper ownerMapper,
136	                                 PetMapper petMapper,
137	                                 VisitMapper visitMapper) {
138	        this.clinicService = clinicService;
139	        this.ownerMapper = ownerMapper;
140	        this.petMapper = petMapper;
141	        this.visitMapper = visitMapper;
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Override
146	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
147	        Collection<Owner> owners;
148	        if (lastName != null) {
149	            owners = this.clinicService.findOwnerByLastName(lastName);
150	        } else {
151	            owners = this.clinicService.findAllOwners();
152	        }
153	        if (owners.isEmpty()) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
167	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
168	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
169	    }
170	
171	    /**
172	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
173	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
174	     * owner sign-ups.
175	     *
176	     * @param registrationDate the day to inspect, or {@code null}
177	     * @return {@code true} when more than the threshold of owners are registered on that day
178	     */
179	    private boolean isBulkSignupDay(LocalDate registrationDate) {
180	        return registrationDate != null
181	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
187	        resolveAddressFields(ownerFieldsDto);
188	        validateRequiredFields(ownerFieldsDto);
189	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
190	        HttpHeaders headers = new HttpHeaders();
191	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
192	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
193	        owner.setEmail(normalizeEmail(owner.getEmail()));
194	        validateRegistrationDate(owner.getRegistrationDate());
195	        if (owner.getRegistrationDate() == null) {
196	            owner.setRegistrationDate(LocalDate.now());
197	        }
198	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
199	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
200	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getPostcode()));
201	        owner.setIdentityKey(buildIdentityKey(owner));
202	        if (!sharesHousehold) {
203	            rejectHouseholdDuplicate(owner.getHouseholdId());
204	        }
205	        Integer possibleDuplicateOf = sharesHousehold ? null : findPossibleDuplicate(owner);
206	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
207	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
208	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
209	            throw new OwnerCityFullException(owner.getCity());
210	        }
211	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
212	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
213	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
214	        }
215	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
216	        owner.setCustomerCode(buildCustomerCode(owner));
217	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
218	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
219	        this.clinicService.saveOwner(owner);
220	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
221	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
222	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
223	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
224	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
225	        headers.setLocation(UriComponentsBuilder.newInstance()
226	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
227	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
228	    }
229	
230	    /**
231	     * Canonicalizes the submitted address fields into the form that is validated, stored and
232	     * returned, before any required-field check or mapping runs. This is the single place a create
233	     * request's address input is resolved.
234	     *
235	     * <p>The structured fields are preferred over the flat input for backward compatibility: when a
236	     * non-blank {@code addressLine1} is supplied, {@code addressLine1} and the optional
237	     * {@code addressLine2} are {@link AddressNormalizer#normalize normalized} in place and the flat
238	     * {@code address} is set to the composed value - the normalized {@code addressLine1}, with a
239	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
240	     * present. When no structured line is supplied the flat {@code address} is normalized in place,
241	     * exactly as before. Either way everything downstream - the required-field check, the mapping onto
242	     * {@link Owner} and the response - sees the canonical address rather than the raw input. A value
243	     * that is blank only after normalization is left blank here and rejected later by
244	     * {@link #validateRequiredFields}.
245	     *
246	     * @param ownerFieldsDto the submitted owner fields, mutated in place with the resolved address
247	     */
248	    private void resolveAddressFields(OwnerFieldsDto ownerFieldsDto) {
249	        String line1 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine1());
250	        String line2 = AddressNormalizer.normalize(ownerFieldsDto.getAddressLine2());
251	        if (!line1.isEmpty()) {
252	            ownerFieldsDto.setAddressLine1(line1);
253	            ownerFieldsDto.setAddressLine2(line2.isEmpty() ? null : line2);
254	            ownerFieldsDto.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
255	        }
256	        else {
257	            ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
258	        }
259	    }
260	
261	    /**
262	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
263	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
264	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
265	     * checked in its resolved form (see {@link #resolveAddressFields}), which is satisfied by either a
266	     * non-blank {@code addressLine1} or the flat {@code address}, so a value that is blank only after
267	     * normalization is still rejected.
268	     *
269	     * @param ownerFieldsDto the submitted owner fields
270	     */
271	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
272	        List<String> missingFields = new ArrayList<>();
273	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
274	            missingFields.add("firstName");
275	        }
276	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
277	            missingFields.add("lastName");
278	        }
279	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
280	            missingFields.add("address");
281	        }
282	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
283	            missingFields.add("city");
284	        }
285	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
286	            missingFields.add("telephone");
287	        }
288	        if (!missingFields.isEmpty()) {
289	            throw new MissingOwnerFieldsException(missingFields);
290	        }
291	    }
292	
293	    /**
294	     * Validates an owner's optional postcode. Postcode is optional, so a missing or blank value is
295	     * accepted unchanged. When a value is supplied it must be exactly four digits; and when the owner's
296	     * city maps to a known region the postcode must fall within that region's inclusive range (checked
297	     * via {@link OwnerLocality#postcodeMatchesCity}, which owns the region table). A city with no known
298	     * region accepts any 4-digit postcode. A malformed or out-of-range postcode is rejected with a 400
299	     * whose {@code errors} array lists {@code postcode}.
300	     *
301	     * @param postcode the submitted postcode, or {@code null} when none was supplied
302	     * @param city the owner's city, whose region determines the acceptable postcode range
303	     * @throws InvalidOwnerFieldsException if a supplied postcode is not four digits or is out of range
304	     */
305	    private void validatePostcode(String postcode, String city) {
306	        if (!StringUtils.hasText(postcode)) {
307	            return;
308	        }
309	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
310	            throw new InvalidOwnerFieldsException(List.of("postcode"));
311	        }
312	        if (!OwnerLocality.postcodeMatchesCity(postcode, city)) {
313	            throw new InvalidOwnerFieldsException(List.of("postcode"));
314	        }
315	    }
316	
317	    /**
318	     * Validates an owner's optional registration date. Registration date is optional, so a missing
319	     * value is accepted (the create later defaults it to the server date). When a value is supplied
320	     * it may not lie in the future: a date later than the server's current date is rejected with a
321	     * 400 whose {@code errors} array lists {@code registrationDate}.
322	     *
323	     * @param registrationDate the submitted registration date, or {@code null} when none was supplied
324	     * @throws InvalidOwnerFieldsException if a supplied date is later than the server date
325	     */
326	    private void validateRegistrationDate(LocalDate registrationDate) {
327	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
328	            throw new InvalidOwnerFieldsException(List.of("registrationDate"));
329	        }
330	    }
331	
332	    /**
333	     * Rejects a submitted owner that would join a household which already has a member. Because the
334	     * {@code householdId} is derived deterministically from the owner's last name and postcode, any
335	     * existing owner sharing that id is the same household, so a second such owner is reported to the
336	     * client as a 409 Conflict. A request may knowingly bypass this block by opting in with
337	     * {@code sharesHousehold}, in which case this check is not performed.
338	     *
339	     * @param householdId the derived household identifier of the owner about to be created
340	     */
341	    private void rejectHouseholdDuplicate(String householdId) {
342	        boolean duplicate = this.clinicService.findAllOwners().stream()
343	            .filter(existing -> !existing.isDeleted())
344	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
345	        if (duplicate) {
346	            throw new DuplicateOwnerIdentityException(householdId);
347	        }
348	    }
349	
350	    /**
351	     * Derives the owner's {@code identityKey}, formatted
352	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
353	     * and email have already been normalized. The household segment always carries the owner's
354	     * deterministic {@code householdId}, since owners with the same last name and postcode belong to
355	     * the same household automatically.
356	     *
357	     * @param owner the normalized owner about to be created, with its {@code householdId} already set
358	     * @return the derived identity key
359	     */
360	    private String buildIdentityKey(Owner owner) {
361	        String email = StringUtils.hasText(owner.getEmail()) ? owner.getEmail() : "";
362	        return owner.getTelephone() + "|" + email + "|" + owner.getHouseholdId();
363	    }
364	
365	    /**
366	     * Detects a soft-match duplicate for the owner about to be created. A soft match is an owner that
367	     * shares an existing owner's {@code lastName} (case-insensitively) and {@code postcode} while
368	     * having a different normalized {@code telephone}. Such an owner is still created, but is flagged
369	     * as a possible duplicate of the matching owner. This is only consulted for owners that did not
370	     * opt into a shared household: an owner that declares {@code sharesHousehold} is a known household
371	     * member, not a suspected duplicate, so it is never flagged. The comparison only applies when a
372	     * postcode was supplied, since both owners must share one; when several existing owners match, the
373	     * earliest (lowest id) is used.
374	     *
375	     * @param owner the normalized owner about to be created, with its telephone already normalized
376	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
377	     */
378	    private Integer findPossibleDuplicate(Owner owner) {
379	        if (!StringUtils.hasText(owner.getPostcode())) {
380	            return null;
381	        }
382	        return this.clinicService.findAllOwners().stream()
383	            .filter(existing -> !existing.isDeleted())
384	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName()))
385	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
386	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
387	            .map(Owner::getId)
388	            .filter(id -> id != null)
389	            .min(Integer::compareTo)
390	            .orElse(null);
391	    }
392	
393	    /**
394	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
395	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
396	     * address; the accepted value is lower-cased before it is stored and returned.
397	     *
398	     * @param email the raw email value submitted by the client, or {@code null}
399	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
400	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
401	     */
402	    private String normalizeEmail(String email) {
403	        if (!StringUtils.hasText(email)) {
404	            return email;
405	        }
406	        if (!EMAIL_PATTERN.matcher(email).matches()) {
407	            throw new InvalidOwnerFieldsException(List.of("email"));
408	        }
409	        String normalized = email.toLowerCase();
410	        String domain = normalized.substring(normalized.indexOf('@') + 1);
411	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
412	            throw new InvalidOwnerFieldsException(List.of("email"));
413	        }
414	        return normalized;
415	    }
416	
417	    /**
418	     * Assigns the owner's customer code, formatted {@code <REGION>-<HASH8>}. The region is derived
419	     * from the owner's postcode (falling back to its city), and the code itself - region plus the
420	     * hash of the owner's normalized telephone and last name - is composed by {@link CustomerCode}.
421	     * When the composed code collides with an existing owner's customer code, it is de-duplicated by
422	     * appending {@code -<n>} with the smallest {@code n} of two or more that makes it unique.
423	     *
424	     * @param owner the normalized owner about to be created
425	     * @return the assigned, de-duplicated customer code
426	     */
427	    private String buildCustomerCode(Owner owner) {
428	        String region = OwnerLocality.forPostcodeAndCity(owner.getPostcode(), owner.getCity());
429	        String code = CustomerCode.forRegionAndIdentity(region, owner.getTelephone(), owner.getLastName());
430	        return deduplicateCustomerCode(code);
431	    }
432	
433	    /**
434	     * De-duplicates a freshly composed customer code against the codes of all existing owners. When
435	     * the code is already unique it is returned unchanged; otherwise {@code -<n>} is appended, using
436	     * the smallest {@code n} of two or more that yields a code no existing owner holds.
437	     *
438	     * @param code the composed customer code, before de-duplication
439	     * @return the same code when unique, otherwise the code with the smallest available {@code -<n>} suffix
440	     */
441	    private String deduplicateCustomerCode(String code) {
442	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
443	            .map(Owner::getCustomerCode)
444	            .filter(existing -> existing != null)
445	            .collect(Collectors.toSet());
446	        if (!existingCodes.contains(code)) {
447	            return code;
448	        }
449	        int suffix = 2;
450	        while (existingCodes.contains(code + "-" + suffix)) {
451	            suffix++;
452	        }
453	        return code + "-" + suffix;
454	    }
455	
456	    /**
457	     * Counts how many owners already exist that share the supplied first and last name, compared
458	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
459	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
460	     *
461	     * @param firstName the submitted owner's first name
462	     * @param lastName the submitted owner's last name
463	     * @return the number of existing owners with the same first and last name, ignoring case
464	     */
465	    private int countNamesakes(String firstName, String lastName) {
466	        return (int) this.clinicService.findAllOwners().stream()
467	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
468	                && lastName.equalsIgnoreCase(existing.getLastName()))
469	            .count();
470	    }
471	
472	    /**
473	     * Counts how many existing owners already belong to the supplied household, identified by its
474	     * {@code householdId}. Used when creating an owner to determine the household's size once the new
475	     * owner is added (this count plus one).
476	     *
477	     * @param householdId the normalized household identifier of the owner being created
478	     * @return the number of existing owners already sharing that {@code householdId}
479	     */
480	    private int countHouseholdMembers(String householdId) {
481	        return (int) this.clinicService.findAllOwners().stream()
482	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
483	            .count();
484	    }
485	
486	    /**
487	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
488	     * enforce the per-city capacity limit when a new owner is created.
489	     *
490	     * @param city the submitted owner's city
491	     * @return the number of existing owners in that city, ignoring case
492	     */
493	    private long countOwnersInCity(String city) {
494	        return this.clinicService.findAllOwners().stream()
495	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
496	            .count();
497	    }
498	
499	    /**
500	     * Counts how many owners have already been created on the supplied registration date. Used to
501	     * enforce the per-day capacity limit when a new owner is created.
502	     *
503	     * @param registrationDate the registration date of the owner being created
504	     * @return the number of existing owners already registered on that date
505	     */
506	    /**
507	     * Rolls a registration date forward to a business day. A registration date must fall on a
508	     * business day, so when the supplied or defaulted date lands on a Saturday, Sunday or a listed
509	     * public holiday it is moved forward to the next non-holiday weekday; a plain weekday is
510	     * returned unchanged. Every value derived from the registration date (such as the membership
511	     * number's year segment) and the daily create-limit therefore use the adjusted date.
512	     *
513	     * @param date the effective registration date, whether supplied or defaulted to the server date
514	     * @return the same date when it is a business day, otherwise the next non-holiday weekday
515	     */
516	    private LocalDate toBusinessDay(LocalDate date) {
517	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
518	            date = date.plusDays(1);
519	        }
520	        return date;
521	    }
522	
523	    private boolean isWeekend(LocalDate date) {
524	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
525	    }
526	
527	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
528	        return this.clinicService.findAllOwners().stream()
529	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
530	            .count();
531	    }
532	
533	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
534	    @Override
535	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
536	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
537	        if (currentOwner == null) {
538	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
539	        }
540	        currentOwner.setAddress(ownerFieldsDto.getAddress());
541	        currentOwner.setCity(ownerFieldsDto.getCity());
542	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
543	        currentOwner.setLastName(ownerFieldsDto.getLastName());
544	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
545	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
546	        this.clinicService.saveOwner(currentOwner);
547	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
548	    }
549	
550	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
551	    @Transactional
552	    @Override
553	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
554	        Owner owner = this.clinicService.findOwnerById(ownerId);
555	        if (owner == null) {
556	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
557	        }
558	        owner.setDeleted(true);
559	        this.clinicService.saveOwner(owner);
560	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
561	    }
562	
563	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
564	    @Override
565	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
566	        Owner owner = this.clinicService.findOwnerById(ownerId);
567	        if (owner == null) {
568	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
569	        }
570	        HttpHeaders headers = new HttpHeaders();
571	        Pet pet = petMapper.toPet(petFieldsDto);
572	        owner.setId(ownerId);
573	        pet.setOwner(owner);
574	        pet.getType().setName(null);
575	        this.clinicService.savePet(pet);
576	        PetDto petDto = petMapper.toPetDto(pet);
577	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
578	            .buildAndExpand(pet.getId()).toUri());
579	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
580	    }
581	
582	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
583	    @Override
584	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
585	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
586	        if (currentOwner != null) {
587	            Pet currentPet = this.clinicService.findPetById(petId);
588	            if (currentPet != null) {
589	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
590	                currentPet.setName(petFieldsDto.getName());
591	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
592	                this.clinicService.savePet(currentPet);
593	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
594	            }
595	        }
596	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
597	    }
598	
599	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
600	    @Override
601	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
602	        HttpHeaders headers = new HttpHeaders();
603	        Visit visit = visitMapper.toVisit(visitFieldsDto);
604	        Pet pet = new Pet();
605	        pet.setId(petId);
606	        visit.setPet(pet);
607	        this.clinicService.saveVisit(visit);
608	        VisitDto visitDto = visitMapper.toVisitDto(visit);
609	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
610	            .buildAndExpand(visit.getId()).toUri());
611	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
612	    }
613	
614	
615	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
616	    @Override
617	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
618	        Owner owner = this.clinicService.findOwnerById(ownerId);
619	        if (owner != null) {
620	            Pet pet = owner.getPet(petId);
621	            if (pet != null) {
622	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
623	            }
624	        }
625	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
626	    }
627	}
